60	  // QB metadata is stored as a JSON suffix after the regular URL
61	  // Format: "original_url||qb:{json}" or just "qb:{json}"
62	  const qbIdx = invoiceUrl.indexOf(QB_PREFIX);
63	  if (qbIdx === -1) return null;
64	
65	  try {
66	    const jsonStr = invoiceUrl.slice(qbIdx + QB_PREFIX.length);
67	    return JSON.parse(jsonStr) as QBSyncMeta;
68	  } catch {
69	    return null;
